from __future__ import annotations

import base64
import io
import shutil
import tarfile
from pathlib import Path

ARCHIVE_B64 = "[...truncated...]" 


def _safe_extract(repo_root: Path) -> None:
    target = repo_root / "STANDALONE_PLATFORMS" / "01_RTBO_Core_Website"
    if target.exists():
        shutil.rmtree(target)

    raw = base64.b64decode(ARCHIVE_B64)
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as archive:
        for member in archive.getmembers():
            resolved = (repo_root / member.name).resolve()
            if repo_root.resolve() not in resolved.parents and resolved != repo_root.resolve():
                raise RuntimeError(f"Unsafe archive member: {member.name}")
        archive.extractall(repo_root)


if __name__ == "__main__":
    _safe_extract(Path.cwd())
